package jp.shinwakai.dsbooks.preview;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public class CastFileServerTest {
 static void check(boolean b){if(!b)throw new AssertionError();}
 static byte[] request(String url,String method,String range,String path)throws Exception{URL u=new URL(url);try(Socket s=new Socket(u.getHost(),u.getPort())){s.setSoTimeout(3000);s.getOutputStream().write((method+" "+(path==null?u.getPath():path)+" HTTP/1.1\r\nHost: localhost\r\n"+(range==null?"":"Range: "+range+"\r\n")+"\r\n").getBytes(StandardCharsets.US_ASCII));return s.getInputStream().readAllBytes();}}
 static String str(byte[] b){return new String(b,StandardCharsets.ISO_8859_1);}
 public static void main(String[] args)throws Exception{File f=File.createTempFile("dsbooks-cast",".m4b");try{try(FileOutputStream out=new FileOutputStream(f)){out.write("0123456789".getBytes());}String url;try(CastFileServer server=new CastFileServer(InetAddress.getLoopbackAddress(),f)){url=server.url();check(str(request(url,"GET",null,null)).endsWith("\r\n\r\n0123456789"));check(str(request(url,"HEAD",null,null)).endsWith("\r\n\r\n"));String ranged=str(request(url,"GET","bytes=2-4",null));check(ranged.contains("206 Partial Content")&&ranged.contains("bytes 2-4/10")&&ranged.endsWith("234"));check(str(request(url,"GET","bytes=-3",null)).endsWith("789"));for(String r:new String[]{"bytes=999-","bytes=4-2","bytes=0-1,3-5","bytes=-0"})check(str(request(url,"GET",r,null)).contains("416 Range"));check(str(request(url,"GET",null,"/wrong")).contains("404 Not Found"));check(str(request(url,"POST",null,null)).contains("405 Method"));try(RandomAccessFile raf=new RandomAccessFile(f,"rw")){raf.setLength(3L*1024*1024*1024);raf.seek(3000000000L);raf.write("LARGE".getBytes());}check(str(request(url,"GET","bytes=3000000000-3000000004",null)).endsWith("LARGE"));}try{request(url,"HEAD",null,null);throw new AssertionError();}catch(IOException expected){}System.out.println("PASS Cast HTTP GET/HEAD/ranges/416/path/method/3GB offsets/close");}finally{f.delete();}}
}
